# make regenerates the tarball's Makefiles with this system's automake, and
# the libtool 2.2 script the tarball carries then refuses to run beside
# them; every generated file is rebuilt first.
autoreconf -fi
./configure --prefix=/usr --libdir=/usr/lib --disable-static
make
make DESTDIR=$PKG install
